USE gram_panchayat;
CREATE VIEW All_Application AS select* from Certificate_Application;
SELECT * FROM All_Application;
CREATE VIEW Application_Status_View AS SELECT application_id, citizen_id, application_status FROM Certificate_Application;
SELECT * FROM Application_Status_View;
CREATE VIEW Approved_Applications AS SELECT * FROM Certificate_Application WHERE application_status = 'Approved';
SELECT * FROM Approved_Applications;
SHOW FULL TABLES WHERE Table_type = 'VIEW';
CREATE VIEW Certificate_Application_View AS SELECT C.certificate_name, A.application_date FROM Certificate_Application A JOIN Certificate_Type C ON A.certificate_id = C.certificate_type_id;
SELECT * FROM Certificate_Application_View;
CREATE VIEW Citizen_Application_View AS SELECT C.full_name, A.application_status FROM Citizen C JOIN Certificate_Application A ON C.citizen_id = A.citizen_id;
SELECT * FROM Citizen_Application_View;
CREATE VIEW Office_Application_View AS SELECT P.office_name, A.application_id FROM Panchayat_Office P JOIN Certificate_Application A ON P.office_id = A.office_id;
SELECT * FROM Office_Application_View;
CREATE VIEW Certificate_Application_Count AS SELECT certificate_id, COUNT(*) AS total_applications FROM Certificate_Application GROUP BY certificate_id;
SELECT * FROM Certificate_Application_Count;
CREATE VIEW Office_Application_Count AS SELECT office_id, COUNT(*) AS total_applications FROM Certificate_Application GROUP BY office_id;
SELECT * FROM Office_Application_Count;
CREATE VIEW Pending_Applications_View AS SELECT A.application_id,C.certificate_name,A.application_date,A.application_status FROM Certificate_Application A JOIN Certificate_Type C ON A.certificate_id = C.certificate_type_id WHERE A.application_status = 'Pending';
SELECT * FROM Pending_Applications_View;
SELECT application_id, certificate_name FROM Pending_Applications_View WHERE application_date >= '2026-01-01';
SHOW CREATE VIEW Pending_Applications_View;
CREATE VIEW Certificate_Total_View AS SELECT C.certificate_name,COUNT(A.application_id) AS total_applications FROM Certificate_Type C JOIN Certificate_Application A ON C.certificate_type_id = A.certificate_id GROUP BY C.certificate_type_id, C.certificate_name;
SELECT * FROM Certificate_Total_View;
CREATE VIEW Office_More_Than_One AS SELECT P.office_name,COUNT(A.application_id) AS total_applications FROM Panchayat_Office P JOIN Certificate_Application A ON P.office_id = A.office_id GROUP BY P.office_id, P.office_name HAVING COUNT(A.application_id) > 1;
SELECT * FROM Office_More_Than_One;
CREATE VIEW Certificate_Date_View AS SELECT C.certificate_name,MIN(A.application_date) AS earliest_date,MAX(A.application_date) AS latest_date FROM Certificate_Type C JOIN Certificate_Application A ON C.certificate_type_id = A.certificate_id GROUP BY C.certificate_type_id, C.certificate_name;
SELECT * FROM Certificate_Date_View;
CREATE VIEW Citizen_Application_Count AS SELECT C.full_name,COUNT(A.application_id) AS total_applications FROM Citizen C JOIN Certificate_Application A ON C.citizen_id = A.citizen_id GROUP BY C.citizen_id, C.full_name;
SELECT * FROM Citizen_Application_Count;
CREATE VIEW Complete_Application_View AS
SELECT C.full_name,T.certificate_name,A.application_id,A.application_date,A.application_status FROM Citizen C JOIN Certificate_Application A ON C.citizen_id = A.citizen_id JOIN Certificate_Type T ON A.certificate_id = T.certificate_type_id;
SELECT * FROM Complete_Application_View;
CREATE VIEW Approved_Details_View AS
SELECT C.full_name,T.certificate_name,A.application_id,A.application_date FROM Certificate_Application A JOIN Citizen C ON A.citizen_id = C.citizen_id JOIN Certificate_Type T ON A.certificate_id = T.certificate_type_id WHERE A.application_status = 'Approved';
SELECT * FROM Approved_Details_View;
SELECT *FROM Citizen_Application_Count WHERE total_applications > 1 ORDER BY total_applications DESC;
DROP VIEW Approved_Details_View;
SHOW FULL TABLES WHERE Table_type = 'VIEW';